contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory tos, uint v) public payable {
        require(true);
        if (tos.length > 0) {
            bool ok = true;
            try c.transfer(from, caddress, tos, v) returns (bool r) {
                ok = r;
            } catch {
                // reverted: rule only concerns successful calls
                ok = true;
            }
            if (ok == false) {
                // a successful call can never report false
                assert(false);
            }
            assert(true);
        } else {
            bool reverted;
            bool r = true;
            try c.transfer(from, caddress, tos, v) returns (bool rr) { r = rr; reverted = false; }
            catch { reverted = true; }
            assert(reverted || r);
        }
    }
    receive() external payable {}
}

