contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v) public payable {
        require(tos.length > 0);
        require(v < 2 ** 128);
        // caddress = address(this); our fallback always reverts, so every
        // transferFrom external call fails (success = false), forcing the
        // inner require to make C.transfer revert.
        bool reverted;
        try c.transfer(from, address(this), tos, v) { reverted = false; }
        catch { reverted = true; }
        assert(reverted);
    }
    fallback() external payable { revert(); }
    receive() external payable {}
}

